[CmdletBinding()]param([string]$RepoRoot='.',[string]$OutputRoot='',[switch]$Force)
$ErrorActionPreference='Stop';$Root=(Resolve-Path $RepoRoot).Path;if([string]::IsNullOrWhiteSpace($OutputRoot)){$OutputRoot=Join-Path $Root '.artifacts\release-kit\1.2.8\action-bridge'};New-Item -ItemType Directory -Force $OutputRoot|Out-Null;$Stage=Join-Path ([IO.Path]::GetTempPath()) ('action-bridge-1.2.8-'+[guid]::NewGuid().ToString('N'));$Pack=Join-Path $Stage 'agentic-action-bridge-1.2.8';New-Item -ItemType Directory -Force $Pack|Out-Null;try{foreach($Name in @('companion_action_bridge.py','Install-CompanionActionBridge.ps1','Run-CompanionActionBridgeWorker.ps1','Import-CompanionActionPacket.ps1','Uninstall-CompanionActionBridge.ps1')){Copy-Item (Join-Path $Root ('scripts\bridge\'+$Name)) $Pack};$V=[ordered]@{schema_version='1.0.0';ecosystem_version='1.2.8';component='action_bridge';version='1.2.8';primary_packet_extension='.json'};[IO.File]::WriteAllText((Join-Path $Pack 'VERSION.json'),($V|ConvertTo-Json),[Text.UTF8Encoding]::new($false));$MF=Get-ChildItem $Pack -File|Sort-Object Name|%{[ordered]@{path=$_.Name;size_bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}};[IO.File]::WriteAllText((Join-Path $Pack 'MANIFEST.json'),([ordered]@{schema_version='1.0.0';ecosystem_version='1.2.8';files=@($MF)}|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$Zip=Join-Path $OutputRoot 'agentic-action-bridge-1.2.8.zip';Compress-Archive -Path (Join-Path $Pack '*') -DestinationPath $Zip -Force;Write-Host "Action Bridge built: $Zip"}finally{Remove-Item $Stage -Recurse -Force -ErrorAction SilentlyContinue}
